function makePath(points,width){const curve=new T.CatmullRomCurve3(points.map(p=>V(p[0],0,p[1]))),pts=curve.getPoints(100),v=[],ids=[];for(let i=0;i<pts.length;i++){const p=pts[i],next=pts[Math.min(i+1,pts.length-1)],prev=pts[Math.max(i-1,0)],dir=next.clone().sub(prev).normalize(),normal=V(-dir.z,0,dir.x);for(const s of [-1,1]){const x=p.x+normal.x*width*s,z=p.z+normal.z*width*s;v.push(x,terrain(x,z)+.035,z);}if(i<pts.length-1){const a=i*2;ids.push(a,a+2,a+1,a+1,a+2,a+3);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(v,3));g.setIndex(ids);g.computeVertexNormals();mesh(g,mat('path','#c9c49c',{roughness:1}),scene);}
