 for(const side of [-1,1]){sphere(root,[side*.53,1.27,0],[.22,.28,.26],bodyMat);box(root,[side*.6,.85,.04],[.24,.48,.27],materials.stoneDark);box(root,[side*.22,.36,.02],[.26,.6,.3],bodyMat);box(root,[side*.22,.12,.12],[.33,.22,.48],materials.stone);const horn=mesh(new T.ConeGeometry(.1,.48,4),materials.gold,root,[side*.24,2,.01]);horn.rotation.z=-side*.4;}
