 const warn=ring(scene,[x,terrain(x,z)+.07,z],boss?6:2.4,'#e17e64',0);const fill=mesh(new T.CircleGeometry(1,48),new T.MeshBasicMaterial({color:'#f19a74',transparent:true,opacity:0,depthWrite:false,side:T.DoubleSide}),scene);fill.rotation.x=-Math.PI/2;fill.position.set(x,terrain(x,z)+.04,z);
 const barC=document.createElement('canvas');barC.width=128;barC.height=12;const barTex=new T.CanvasTexture(barC);const bar=new T.Sprite(new T.SpriteMaterial({map:barTex,transparent:true,depthTest:false}));bar.position.y=2.55;bar.scale.set(1.5,.14,1);root.add(bar);bar.visible=false;
 const e={id,type,guard,root,x,z,origin:V(x,0,z),hp:boss?420:type==='ranged'?64:82,maxHp:boss?420:type==='ranged'?64:82,scale,bodyMat,core,warn,fill,bar,barC,barTex,phase:rand(0,TAU),state:'idle',timer:rand(.3,1.2),cooldown:rand(1,2),knock:V(),knockY:0,vy:0,flash:0,dead:state.dead.includes(id)||(boss&&state.bossDead),dormant:boss&&state.runes.length<3,attackDir:V(),attacked:false,dodged:false};
